def write_error():
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write("============================================================\n")
            f.write(time.strftime("%Y-%m-%d %H:%M:%S") + "\n")
            f.write(traceback.format_exc())
            f.write("\n")
    except Exception:
        return


def write_log(line):
    try:
        with open(LOG_PATH, "a", encoding="utf-8") as f:
            f.write("[%s] %s\n" % (time.strftime("%H:%M:%S"), line))
    except Exception:
        return


