def find_setup():
    for name in ("setup.txt", "SETUP.TXT", "Setup.txt"):
        path = os.path.join(BASE_DIR, name)
        if os.path.isfile(path):
            return path
    return os.path.join(BASE_DIR, "setup.txt")


def ensure_setup():
    path = find_setup()
    if os.path.isfile(path):
        return path
    try:
        os.makedirs(BASE_DIR, exist_ok=True)
        with open(path, "w", encoding="utf-8-sig", newline="\r\n") as f:
            f.write(SETUP_TEXT.strip() + "\r\n")
        write_log("создан setup.txt")
    except Exception:
        write_error()
    return path


def _yes(val, default=True):
    if val is None or str(val).strip() == "":
        return default
    s = str(val).strip().lower()
    if s in ("0", "нет", "no", "off", "выкл", "false"):
        return False
    if s in ("1", "да", "yes", "on", "вкл", "true"):
        return True
    return default


def _speed(cfg):
    raw = str(cfg.get("СКОРОСТЬ") or "1").strip().lower().replace(",", ".")
    names = {"медленно": 0.7, "обычно": 1.0, "быстро": 1.6}
    if raw in names:
        return names[raw]
    try:
        return max(0.45, min(2.2, float(raw)))
    except Exception:
        return 1.0


def load_setup():
    ensure_setup()
    cfg = {
        "ГОРОД": "Barnaul",
        "API_КЛЮЧ": "3ab9cda25706a200fd32acda7d4888b1",
        "СКОРОСТЬ": "обычно",
        "ГОЛОС": "да",
    }
    path = find_setup()
    try:
        with open(path, "r", encoding="utf-8") as f:
            for line in f:
                line = line.strip()
                if not line or line[0] in "#[═─":
                    continue
                if "=" not in line:
                    continue
                key, val = line.split("=", 1)
                key = key.strip().upper()
                val = val.split("#", 1)[0].strip()
                if key:
                    cfg[key] = val
    except Exception:
        write_error()
    return cfg


def temp_words(temp):
    ones = (
        "ноль", "один", "два", "три", "четыре",
        "пять", "шесть", "семь", "восемь", "девять",
    )
    teens = (
        "десять", "одиннадцать", "двенадцать", "тринадцать", "четырнадцать",
        "пятнадцать", "шестнадцать", "семнадцать", "восемнадцать", "девятнадцать",
    )
    tens = (
        "", "", "двадцать", "тридцать", "сорок", "пятьдесят",
        "шестьдесят", "семьдесят", "восемьдесят", "девяносто",
    )

    def words(n):
        n = max(0, min(99, int(n)))
        if n < 10:
            return ones[n]
        if n < 20:
            return teens[n - 10]
        ten, one = divmod(n, 10)
        if one == 0:
            return tens[ten]
        return "%s %s" % (tens[ten], ones[one])

    sign = "минус " if temp < 0 else ""
    abs_v = round(abs(float(temp)), 1)
    whole = int(abs_v)
    tenth = int(round((abs_v - whole) * 10))
    if tenth == 10:
        whole += 1
        tenth = 0
    body = "%s и %s" % (words(whole), ones[tenth])
    return sign + body


def format_temp(temp):
    if temp is None:
        return "—"
    sign = "−" if float(temp) < 0 else ""
    abs_v = round(abs(float(temp)), 1)
    whole = int(abs_v)
    tenth = int(round((abs_v - whole) * 10))
    if tenth == 10:
        whole += 1
        tenth = 0
    return "%s%d,%d°" % (sign, whole, tenth)


def get_weather(city, api_key):
    url = (
        "http://api.openweathermap.org/data/2.5/weather"
        "?q=%s&appid=%s&units=metric&lang=ru" % (city, api_key)
    )
    response = requests.get(url, timeout=4)
    response.raise_for_status()
    d = response.json()
    coord = d.get("coord") or {}
    wind = d.get("wind") or {}
    w0 = (d.get("weather") or [{}])[0]
    return {
        "temp": round(d["main"]["temp"], 1),
        "condition_id": w0.get("id", 800),
        "main": w0.get("main") or "Погода",
        "description": w0.get("description") or w0.get("main") or "Погода",
        "wind_speed": wind.get("speed", 0) or 0,
        "wind_deg": wind.get("deg", 0) or 0,
        "rain_1h": (d.get("rain") or {}).get("1h", 0) or 0,
        "snow_1h": (d.get("snow") or {}).get("1h", 0) or 0,
        "clouds_all": (d.get("clouds") or {}).get("all", 0) or 0,
        "humidity": (d.get("main") or {}).get("humidity", 50) or 50,
        "timezone": d.get("timezone", 0) or 0,
        "sunrise": (d.get("sys") or {}).get("sunrise") or 0,
        "sunset": (d.get("sys") or {}).get("sunset") or 0,
        "lat": coord.get("lat", _DEFAULT_LAT),
        "lon": coord.get("lon", _DEFAULT_LON),
        "dt": d.get("dt", int(time.time())),
    }


def solar_state(lat, lon, unix_utc):
    dt = datetime.fromtimestamp(float(unix_utc), timezone.utc)
    n = dt.timetuple().tm_yday
    minutes = dt.hour * 60 + dt.minute + dt.second / 60.0
    gamma = (2 * math.pi / 365.0) * (n - 1 + (minutes - 720.0) / 1440.0)
    eqtime = 229.18 * (
        0.000075
        + 0.001868 * math.cos(gamma)
        - 0.032077 * math.sin(gamma)
        - 0.014615 * math.cos(2 * gamma)
        - 0.040849 * math.sin(2 * gamma)
    )
    decl = (
        0.006918
        - 0.399912 * math.cos(gamma)
        + 0.070257 * math.sin(gamma)
        - 0.006758 * math.cos(2 * gamma)
        + 0.000907 * math.sin(2 * gamma)
        - 0.002697 * math.cos(3 * gamma)
        + 0.00148 * math.sin(3 * gamma)
    )
    tst = minutes + eqtime + 4.0 * float(lon)
    ha = tst / 4.0 - 180.0
    while ha > 180.0:
        ha -= 360.0
    while ha < -180.0:
        ha += 360.0
    latr = math.radians(float(lat))
    har = math.radians(ha)
    cosz = (
        math.sin(latr) * math.sin(decl)
        + math.cos(latr) * math.cos(decl) * math.cos(har)
    )
    cosz = max(-1.0, min(1.0, cosz))
    elev = 90.0 - math.degrees(math.acos(cosz))
    setting = ha > 0.0
    if elev < -6.0:
        tod = "night"
    elif elev < 10.0 and not setting:
        tod = "morning"
    elif elev < 12.0 and setting:
        tod = "evening"
    else:
        tod = "day"
    return elev, ha, tod


def sky_clock(weather):
    now = time.time()
    lat = float((weather or {}).get("lat") or _DEFAULT_LAT)
    lon = float((weather or {}).get("lon") or _DEFAULT_LON)
    elev, ha, _guess = solar_state(lat, lon, now)
    sunrise = float((weather or {}).get("sunrise") or 0)
    sunset = float((weather or {}).get("sunset") or 0)
    if sunrise > 0 and sunset > sunrise:
        # Солнце только между восходом и закатом. Утро — до 10:30 по времени города.
        tz = int((weather or {}).get("timezone") or 0)
        local_sec = int(now + tz) % 86400
        morning_end = 10 * 3600 + 30 * 60
        if now < sunrise or now >= sunset:
            tod = "night"
        elif local_sec < morning_end:
            tod = "morning"
        elif now > sunset - 40 * 60:
            tod = "evening"
        else:
            tod = "day"
        def hm(ts):
            return (datetime.fromtimestamp(ts, timezone.utc) + timedelta(seconds=tz)).strftime("%H:%M")
        write_log("свет: восход %s закат %s сейчас %s tod=%s" % (hm(sunrise), hm(sunset), hm(now), tod))
    elif elev <= 0.0:
        tod = "night"
    elif elev < 8.0 and ha <= 0:
        tod = "morning"
    elif elev < 8.0 and ha > 0:
        tod = "evening"
    else:
        tod = "day"
    return tod, now, elev


def scenario_from_weather(weather):
    if not weather:
        sc = {
            "id": 800,
            "title": "Погода",
            "temp": 0.0,
            "wind": 0.0,
            "deg": 0.0,
            "clouds": 0.0,
            "rain": 0.0,
            "snow": 0.0,
            "hum": 50.0,
        }
    else:
        sc = {
            "id": int(weather.get("condition_id") or 800),
            "title": str(weather.get("description") or weather.get("main") or "Погода"),
            "temp": float(weather.get("temp") or 0.0),
            "wind": float(weather.get("wind_speed") or 0.0),
            "deg": float(weather.get("wind_deg") or 0.0),
            "clouds": float(weather.get("clouds_all") or 0.0),
            "rain": float(weather.get("rain_1h") or 0.0),
            "snow": float(weather.get("snow_1h") or 0.0),
            "hum": float(weather.get("humidity") or 50.0),
        }
    wid = int(sc["id"])
    if sc["rain"] <= 0.05:
        if wid == 500:
            sc["rain"] = 0.7
        elif wid in (501, 520):
            sc["rain"] = 2.4
        elif wid in (502, 521, 531):
            sc["rain"] = 8.0
        elif wid in (503, 504, 522):
            sc["rain"] = 16.0
        elif 300 <= wid < 400:
            sc["rain"] = 0.35
        elif 200 <= wid < 300:
            sc["rain"] = 1.4 if wid in (200, 210, 230) else 3.5
        elif wid == 511:
            sc["rain"] = 1.2
    if sc["snow"] <= 0.05 and 600 <= wid <= 622:
        if wid in (600, 620):
            sc["snow"] = 0.4
        elif wid in (601, 612, 615, 616, 621):
            sc["snow"] = 1.5
        else:
            sc["snow"] = 4.5
    if (sc["rain"] > 0.25 or sc["snow"] > 0.25) and sc["clouds"] < 45:
        sc["clouds"] = 62
    title = sc["title"].strip()
    if title:
        sc["title"] = title[0].upper() + title[1:]
    return sc


def _play_mp3(path):
    import ctypes
    from ctypes import wintypes as wt

    winmm = ctypes.WinDLL("winmm")
    winmm.mciSendStringW.argtypes = [wt.LPCWSTR, wt.LPWSTR, wt.UINT, wt.HANDLE]
    winmm.mciSendStringW.restype = wt.DWORD
    alias = "stekloVoice"
    winmm.mciSendStringW("close " + alias, None, 0, None)
    err = winmm.mciSendStringW(
        'open "' + path + '" type mpegvideo alias ' + alias, None, 0, None
    )
    if err:
        return False
    winmm.mciSendStringW("play " + alias + " wait", None, 0, None)
    winmm.mciSendStringW("close " + alias, None, 0, None)
    return True


def _speak_edge(text, ready):
    import asyncio
    import tempfile

    import edge_tts

    path = os.path.join(tempfile.gettempdir(), "steklo_voice.mp3")

    async def run():
        com = edge_tts.Communicate(text, "ru-RU-SvetlanaNeural", rate="-6%")
        await asyncio.wait_for(com.save(path), timeout=7)

    asyncio.run(run())
    if not os.path.isfile(path) or os.path.getsize(path) < 400:
        return False
    if ready is not None:
        ready.wait(timeout=12)
    return _play_mp3(path)


def _bundled_voice(temperature):
    v = round(abs(float(temperature)), 1)
    whole = int(v)
    tenth = int(round((v - whole) * 10))
    if tenth == 10:
        whole += 1
        tenth = 0
    sign = "m" if float(temperature) < 0 else ""
    key = sign + ("%d_%d" % (whole, tenth))
    folders = []
    if _APP_DIR:
        folders.append(os.path.join(_APP_DIR, "voice"))
    folders.append(os.path.join(BASE_DIR, "public", "voice"))
    folders.append(os.path.join(BASE_DIR, "voice"))
    for folder in folders:
        path = os.path.join(folder, key + ".mp3")
        if os.path.isfile(path) and os.path.getsize(path) > 400:
            return path
    return None


def speak_temperature(temperature, ready=None):
    if temperature is None:
        return
    text = temp_words(temperature)
    write_log("голос: " + text)
    clip = _bundled_voice(temperature)
    if clip:
        try:
            if ready is not None:
                ready.wait(timeout=12)
            if _play_mp3(clip):
                write_log("голос: запись из теста")
                return
        except Exception:
            write_error()
    try:
        if _speak_edge(text, ready):
            write_log("голос: женский")
            return
    except Exception:
        write_error()
    try:
        import pyttsx3

        engine = pyttsx3.init()
        voices = list(engine.getProperty("voices") or [])
        female = ("irina", "ирина", "milena", "милена", "katya", "elena", "svetlana", "alena", "zira", "жен")
        male = ("dmitri", "dmitry", "pavel", "yuri", "filipp", "муж")

        def score(v):
            blob = ("%s %s" % (getattr(v, "name", ""), getattr(v, "id", ""))).lower()
            s = 0
            if "ru" in blob or "russian" in blob or "рус" in blob:
                s += 3
            if any(k in blob for k in female):
                s += 8
            if any(k in blob for k in male):
                s -= 8
            return s

        if voices:
            engine.setProperty("voice", max(voices, key=score).id)
        try:
            engine.setProperty("rate", 156)
        except Exception:
            pass
        if ready is not None:
            ready.wait(timeout=12)
        engine.say(text)
        engine.runAndWait()
    except Exception:
        write_error()


def show_simple(temperature, ready):
    from tkinter import Label, Tk

    root = Tk()
    root.configure(background="black")
    root.overrideredirect(True)
    root.attributes("-topmost", True)
    try:
        root.attributes("-transparentcolor", "black")
    except Exception:
        pass
    label = Label(
        root,
        text=format_temp(temperature),
        font=("Segoe UI", 72, "bold"),
        fg="#d7f3ff",
        bg="black",
    )
    label.pack(expand=True, padx=40, pady=24)
    root.update_idletasks()
    w = root.winfo_width()
    h = root.winfo_height()
    x = max(0, (root.winfo_screenwidth() - w) // 2)
    y = max(0, (root.winfo_screenheight() - h) // 2)
    root.geometry("+%d+%d" % (x, y))
    root.update()
    ready.set()
    root.after(4800, root.destroy)
    root.mainloop()


