def _glass_clock(cfg):
    speed = _speed(cfg)
    # Чуть быстрее появление/исчезновение — меньше «ожидания картинки».
    return 0.72 / speed, 3.0 / speed, 1.85 / speed


def _screen_box():
    if sys.platform != "win32":
        return 0, 0, 1280, 720
    import ctypes

    try:
        ctypes.windll.shcore.SetProcessDpiAwareness(2)
    except Exception:
        try:
            ctypes.windll.user32.SetProcessDPIAware()
        except Exception:
            pass
    user = ctypes.windll.user32
    w = int(user.GetSystemMetrics(0))
    h = int(user.GetSystemMetrics(1))
    x = 0
    y = 0
    try:
        class RECT(ctypes.Structure):
            _fields_ = (
                ("l", ctypes.c_long),
                ("t", ctypes.c_long),
                ("r", ctypes.c_long),
                ("b", ctypes.c_long),
            )

        rect = RECT()
        user.SystemParametersInfoW.argtypes = [ctypes.c_uint, ctypes.c_uint, ctypes.c_void_p, ctypes.c_uint]
        user.SystemParametersInfoW.restype = ctypes.c_bool
        if user.SystemParametersInfoW(48, 0, ctypes.byref(rect), 0):
            x, y = int(rect.l), int(rect.t)
            w, h = int(rect.r - rect.l), int(rect.b - rect.t)
    except Exception:
        pass
    scale = 1.0
    try:
        dpi = int(user.GetDpiForSystem())
        if dpi > 0:
            scale = dpi / 96.0
    except Exception:
        scale = 1.0
    if scale < 1:
        scale = 1.0
    return int(round(x / scale)), int(round(y / scale)), max(640, int(round(w / scale))), max(480, int(round(h / scale)))


def _import_webview():
    try:
        import webview
        return webview
    except ImportError:
        subprocess.check_call(
            [sys.executable, "-m", "pip", "install", "--disable-pip-version-check", "pywebview"]
        )
        import webview
        return webview


def prepare_app():
    global _APP_DIR
    # Локальная папка glass/ удобна при разработке; в одном файле — pack.
    if os.path.isfile(os.path.join(GLASS_DIR, "index.html")):
        _APP_DIR = GLASS_DIR
        return GLASS_DIR
    blob = (_PACK_B64 or "").strip()
    if blob:
        import base64
        import hashlib
        import io
        import zipfile

        # Хэш от строки — без тяжёлого b64decode на каждый запуск, если уже распаковано.
        digest = hashlib.sha256(blob.encode("ascii")).hexdigest()[:16]
        dest = os.path.join(tempfile.gettempdir(), "steklo-app-" + digest)
        marker = os.path.join(dest, "index.html")
        if not os.path.isfile(marker):
            raw = base64.b64decode(blob.encode("ascii"))
            os.makedirs(dest, exist_ok=True)
            with zipfile.ZipFile(io.BytesIO(raw)) as packed:
                packed.extractall(dest)
        _APP_DIR = dest
        return dest
    _APP_DIR = None
    return None


def _hwnd_of(native):
    handle = native.Handle
    if hasattr(handle, "ToInt64"):
        return handle.ToInt64()
    return int(handle)


def _dwm_cloak(hwnd, cloaked):
    if sys.platform != "win32" or not hwnd:
        return
    try:
        import ctypes

        flag = ctypes.c_int(1 if cloaked else 0)
        dwm = ctypes.windll.dwmapi
        dwm.DwmSetWindowAttribute.argtypes = [
            ctypes.c_void_p,
            ctypes.c_int,
            ctypes.c_void_p,
            ctypes.c_int,
        ]
        dwm.DwmSetWindowAttribute.restype = ctypes.c_long
        # DWMWA_CLOAK = 13 — полностью скрывает окно из композиции без вспышки.
        dwm.DwmSetWindowAttribute(hwnd, 13, ctypes.byref(flag), ctypes.sizeof(flag))
    except Exception:
        pass


def _clear_backdrop(window):
    # Только цвет стекла. Рамку и размер не трогаем — из-за этого окно зависало.
    if sys.platform != "win32":
        return
    if getattr(window, "_steklo_glass", False):
        return
    native = getattr(window, "native", None)
    if native is None:
        write_log("стекло: нет окна")
        return
    try:
        from System.Drawing import Color

        native.BackColor = Color.Black
    except Exception:
        write_error()
    try:
        import ctypes

        hwnd = _hwnd_of(native)

        class MARGINS(ctypes.Structure):
            _fields_ = (
                ("cxLeftWidth", ctypes.c_int),
                ("cxRightWidth", ctypes.c_int),
                ("cyTopHeight", ctypes.c_int),
                ("cyBottomHeight", ctypes.c_int),
            )

        margins = MARGINS(-1, -1, -1, -1)
        dwm = ctypes.windll.dwmapi
        dwm.DwmExtendFrameIntoClientArea.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
        dwm.DwmExtendFrameIntoClientArea.restype = ctypes.c_long
        hr = dwm.DwmExtendFrameIntoClientArea(hwnd, ctypes.byref(margins))
        try:
            none = ctypes.c_int(1)
            dwm.DwmSetWindowAttribute.argtypes = [
                ctypes.c_void_p,
                ctypes.c_int,
                ctypes.c_void_p,
                ctypes.c_int,
            ]
            dwm.DwmSetWindowAttribute.restype = ctypes.c_long
            # DWMWA_TRANSITIONS_FORCEDISABLED — без анимации появления Win11.
            dwm.DwmSetWindowAttribute(hwnd, 3, ctypes.byref(none), ctypes.sizeof(none))
            dwm.DwmSetWindowAttribute(hwnd, 38, ctypes.byref(none), ctypes.sizeof(none))
        except Exception:
            pass

        class ACCENTPOLICY(ctypes.Structure):
            _fields_ = (
                ("AccentState", ctypes.c_int),
                ("AccentFlags", ctypes.c_int),
                ("GradientColor", ctypes.c_uint),
                ("AnimationId", ctypes.c_int),
            )

        class WINCOMPATTRDATA(ctypes.Structure):
            _fields_ = (
                ("Attribute", ctypes.c_int),
                ("Data", ctypes.c_void_p),
                ("SizeOfData", ctypes.c_size_t),
            )

        accent = ACCENTPOLICY()
        accent.AccentState = 2
        accent.AccentFlags = 2
        accent.GradientColor = 0
        comp = WINCOMPATTRDATA()
        comp.Attribute = 19
        comp.SizeOfData = ctypes.sizeof(accent)
        comp.Data = ctypes.addressof(accent)
        user = ctypes.windll.user32
        set_comp = getattr(user, "SetWindowCompositionAttribute", None)
        if set_comp is not None:
            set_comp.argtypes = [ctypes.c_void_p, ctypes.c_void_p]
            set_comp.restype = ctypes.c_int
            set_comp(hwnd, ctypes.byref(comp))
        if not getattr(_fade_in, "revealed", False):
            _dwm_cloak(hwnd, True)
            try:
                native.Opacity = 0
            except Exception:
                pass
        window._steklo_glass = True
        write_log("стекло: стол %s" % hr)
    except Exception:
        write_error()


def _quiet_webview():
    # Окно рождается невидимым: Opacity=0 + DWM cloak, без белого кадра WinForms.
    try:
        from webview.platforms.winforms import BrowserView

        Form = BrowserView.BrowserForm
        if not getattr(Form, "_steklo_quiet", False):
            orig_init = Form.__init__

            def quiet_init(self, window, cache_dir):
                orig_init(self, window, cache_dir)
                try:
                    self.Opacity = 0
                except Exception:
                    pass
                try:
                    self.ShowInTaskbar = False
                except Exception:
                    pass
                try:
                    hwnd = self.Handle.ToInt64() if hasattr(self.Handle, "ToInt64") else int(self.Handle)
                    _dwm_cloak(hwnd, True)
                except Exception:
                    pass

            Form.__init__ = quiet_init
            Form._steklo_quiet = True
    except Exception:
        write_error()
    try:
        from webview.platforms.edgechromium import EdgeChrome

        if not getattr(EdgeChrome, "_steklo_quiet", False):
            orig = EdgeChrome.on_navigation_start

            def on_navigation_start(self, sender, args):
                try:
                    self.form.Opacity = 0
                except Exception:
                    pass
                try:
                    hwnd = (
                        self.form.Handle.ToInt64()
                        if hasattr(self.form.Handle, "ToInt64")
                        else int(self.form.Handle)
                    )
                    if not getattr(_fade_in, "revealed", False):
                        _dwm_cloak(hwnd, True)
                except Exception:
                    pass
                orig(self, sender, args)
                try:
                    self.form.Opacity = 0
                except Exception:
                    pass

            EdgeChrome.on_navigation_start = on_navigation_start
            EdgeChrome._steklo_quiet = True
    except Exception:
        write_error()


def _cloak(window):
    if getattr(_fade_in, "revealed", False):
        return
    native = getattr(window, "native", None)
    if native is None:
        return

    def zero():
        if getattr(_fade_in, "revealed", False):
            return
        try:
            native.Opacity = 0
        except Exception:
            pass
        try:
            _dwm_cloak(_hwnd_of(native), True)
        except Exception:
            pass

    try:
        from System import Action

        native.BeginInvoke(Action(zero))
    except Exception:
        zero()


def _fade_in(window):
    if getattr(_fade_in, "revealed", False):
        return
    _fade_in.revealed = True
    native = getattr(window, "native", None)
    if native is None:
        try:
            window.show()
        except Exception:
            pass
        return

    def start():
        try:
            hwnd = _hwnd_of(native)
        except Exception:
            hwnd = 0
        # Сначала opacity=0, потом снимаем cloak — иначе один чёрный кадр.
        try:
            native.Opacity = 0
        except Exception:
            pass
        _dwm_cloak(hwnd, False)
        try:
            if not bool(getattr(native, "Visible", True)):
                native.Show()
        except Exception:
            try:
                window.show()
            except Exception:
                pass
        try:
            native.Opacity = 0
        except Exception:
            write_error()
            return
        try:
            native.Activate()
        except Exception:
            pass
        try:
            from System.Windows.Forms import Timer
        except Exception:
            try:
                native.Opacity = 1
            except Exception:
                pass
            return
        box = {"i": 0}
        steps = 14
        timer = Timer()
        _fade_in.timer = timer
        timer.Interval = 16

        def tick(_sender, _e):
            box["i"] += 1
            t = min(1.0, box["i"] / float(steps))
            # мягкий ease-out
            fade = 1.0 - (1.0 - t) ** 2.6
            try:
                native.Opacity = fade
            except Exception:
                timer.Stop()
                return
            if box["i"] >= steps:
                try:
                    native.Opacity = 1
                except Exception:
                    pass
                timer.Stop()
                try:
                    timer.Dispose()
                except Exception:
                    pass

        timer.Tick += tick
        timer.Start()

    try:
        from System import Action

        native.BeginInvoke(Action(start))
    except Exception:
        write_error()
        try:
            native.Opacity = 1
            window.show()
        except Exception:
            pass


def _open_window(url, bye, reveal=None):
    # Полностью прозрачный фон WebView2 — без белой вспышки.
    os.environ["WEBVIEW2_DEFAULT_BACKGROUND_COLOR"] = "00000000"
    webview = _import_webview()
    _quiet_webview()
    _fade_in.revealed = False
    x, y, w, h = _screen_box()
    base = dict(
        title="Стекло",
        url=url,
        x=x,
        y=y,
        width=max(640, w),
        height=max(480, h),
        frameless=True,
        on_top=True,
        focus=False,
        easy_drag=False,
    )
    window = None
    last = None
    attempts = (
        dict(base, transparent=True, background_color="#00000000", shadow=False, hidden=True),
        dict(base, transparent=True, background_color="#000000", shadow=False, hidden=True),
        dict(base, transparent=True, background_color="#00000000", shadow=False),
        dict(base, transparent=True, background_color="#000000", shadow=False),
        dict(base, transparent=True, shadow=False),
        dict(base, background_color="#000000", shadow=False),
        dict(base),
    )
    for extra in attempts:
        try:
            window = webview.create_window(**extra)
            write_log(
                "окно: %s%s"
                % (
                    "прозрачное" if extra.get("transparent") else "обычное",
                    " скрытое" if extra.get("hidden") else "",
                )
            )
            break
        except TypeError as exc:
            # Старый pywebview без hidden / #AARRGGBB.
            last = exc
            window = None
        except Exception as exc:
            last = exc
            window = None
            write_log("окно не подошло: %s" % exc)
    if window is None:
        raise last or RuntimeError("окно")

    def on_glass(*_args):
        _clear_backdrop(window)
        _cloak(window)

    def on_loaded(*_args):
        _clear_backdrop(window)
        _cloak(window)

        def wait_paint():
            if reveal is not None:
                reveal.wait(timeout=2.0)
            _fade_in(window)
            try:
                window.show()
            except Exception:
                pass

        threading.Thread(target=wait_paint, daemon=True).start()

    try:
        window.events.shown += on_glass
    except Exception:
        write_error()
    try:
        window.events.loaded += on_loaded
    except Exception:
        write_error()

    def reveal_anyway():
        time.sleep(4.5)
        _fade_in(window)
        try:
            window.show()
        except Exception:
            pass

    threading.Thread(target=reveal_anyway, daemon=True).start()

    def close_when_done():
        bye.wait()
        try:
            window.destroy()
        except Exception:
            pass

    threading.Thread(target=close_when_done, daemon=True).start()
    print("Открываю картинку...")
    webview.start(debug=False)


def _file_cache(root):
    cache = {}
    try:
        for dirpath, _dirs, files in os.walk(root):
            for name in files:
                full = os.path.join(dirpath, name)
                rel = os.path.relpath(full, root).replace("\\", "/")
                try:
                    with open(full, "rb") as f:
                        cache[rel] = f.read()
                except Exception:
                    pass
    except Exception:
        write_error()
    return cache


def show(temperature, weather, cfg, ready_voice):
    root = prepare_app()
    if not root:
        write_log("нет картинки стекла")
        show_simple(temperature, ready_voice)
        return None

    tod, _unix, elev = sky_clock(weather)
    write_log("tod=%s elev=%.1f" % (tod, elev))
    appear, _hold, out = _glass_clock(cfg)
    live = {
        "scenario": scenario_from_weather(weather),
        "tod": tod,
        "appear": appear,
        "hold": _hold,
        "out": out,
    }
    payload = json.dumps(live, ensure_ascii=False).encode("utf-8")
    inject = (
        "<script>window.__STEKLO__=%s;</script>"
        % json.dumps(live, ensure_ascii=False)
    ).encode("utf-8")

    ready = threading.Event()
    bye = threading.Event()
    files = _file_cache(root)

    class Handler(BaseHTTPRequestHandler):
        def log_message(self, fmt, *args):
            return

        def _send(self, code, body, ctype, cache="no-store"):
            self.send_response(code)
            self.send_header("Content-Type", ctype)
            self.send_header("Cache-Control", cache)
            self.send_header("Content-Length", str(len(body)))
            self.end_headers()
            if self.command != "HEAD":
                self.wfile.write(body)

        def _route(self):
            path = unquote(urlparse(self.path).path)
            if path in ("/ready", "/bye"):
                if path == "/ready":
                    ready.set()
                else:
                    bye.set()
                self._send(204, b"", "text/plain")
                return
            if path == "/live.json":
                self._send(200, payload, "application/json; charset=utf-8")
                return
            rel = "index.html" if path in ("/", "") else path.lstrip("/")
            rel = rel.replace("\\", "/")
            if rel.startswith("../") or "/../" in rel or rel == "..":
                self._send(404, b"", "text/plain")
                return
            data = files.get(rel)
            if data is None:
                base = os.path.normpath(root)
                full = os.path.normpath(os.path.join(base, rel))
                if not (full == base or full.startswith(base + os.sep)) or not os.path.isfile(full):
                    self._send(404, b"", "text/plain")
                    return
                with open(full, "rb") as f:
                    data = f.read()
            if rel == "index.html":
                # Вшиваем погоду в HTML — без лишнего fetch до первой отрисовки.
                if b"window.__STEKLO__" not in data:
                    if b"</head>" in data:
                        data = data.replace(b"</head>", inject + b"</head>", 1)
                    else:
                        data = inject + data
                self._send(200, data, "text/html; charset=utf-8", "no-store")
                return
            ext = os.path.splitext(rel)[1].lower()
            cache = "public, max-age=86400" if ext in (".ttf", ".png", ".js", ".mp3", ".woff2") else "no-store"
            self._send(200, data, _MIME.get(ext, "application/octet-stream"), cache)

        def do_GET(self):
            self._route()

        def do_HEAD(self):
            self._route()

        def do_POST(self):
            self._route()

    httpd = None
    port = 47123
    for port in range(47123, 47143):
        try:
            httpd = ThreadingHTTPServer(("127.0.0.1", port), Handler)
            break
        except OSError:
            httpd = None
    if httpd is None:
        write_log("не открылся показ")
        show_simple(temperature, ready_voice)
        return None

    httpd.daemon_threads = True
    threading.Thread(target=httpd.serve_forever, daemon=True).start()
    url = "http://127.0.0.1:%d/" % port

    def bridge():
        ready.wait(timeout=12)
        ready_voice.set()

    threading.Thread(target=bridge, daemon=True).start()
    try:
        _open_window(url, bye, ready)
    except Exception:
        write_error()
        write_log("прозрачное окно не открылось")
        if not ready_voice.is_set():
            ready_voice.set()
    finally:
        bye.set()
        if not ready_voice.is_set():
            ready_voice.set()
        try:
            httpd.shutdown()
        except Exception:
            pass
    return None


def _preload_webview():
    try:
        _import_webview()
        _quiet_webview()
    except Exception:
        write_error()


def main():
    write_log("--- START ---")
    # Параллельно: WebView2, распаковка картинки, setup, погода.
    threading.Thread(target=_preload_webview, daemon=True).start()
    app_ready = threading.Event()

    def warm_app():
        try:
            prepare_app()
        finally:
            app_ready.set()

    threading.Thread(target=warm_app, daemon=True).start()
    cfg = load_setup()

    weather = None
    temperature = None
    try:
        weather = get_weather(str(cfg.get("ГОРОД") or "Barnaul"), str(cfg.get("API_КЛЮЧ") or ""))
        temperature = weather["temp"]
        write_log("temperature = %s" % temperature)
    except Exception:
        write_error()

    app_ready.wait(timeout=8)

    voice_ready = threading.Event()
    voice = None
    if temperature is not None and _yes(cfg.get("ГОЛОС"), True):
        voice = threading.Thread(
            target=speak_temperature,
            args=(temperature, voice_ready),
            daemon=True,
        )
        voice.start()
    try:
        show(temperature, weather, cfg, voice_ready)
    except Exception:
        write_error()
        if not voice_ready.is_set():
            voice_ready.set()
    if voice is not None:
        voice.join(timeout=20)
    write_log("--- END ---")


if __name__ == "__main__":
    main()
